"""Compose completed bounded evidence groups; preserve both incomplete diagnostics."""
from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent
main=json.loads((H/'diagnostic-main54-assumption-results.json').read_text())
supp=json.loads((H/'supplement-results.json').read_text())
natural=json.loads((H/'natural-entry-results.json').read_text())
comp=json.loads((H/'comparison-captures.json').read_text())
failed=[c for c in main['checks'] if not c['passed']]
assert len(failed)==1 and failed[0]['label']=='Main54 reads earned lesson progress',failed
assert supp['passed'] and natural['passed'] and comp['passed']
assert main['sourceSHA256']==supp['sourceSHA256']
checks=[c for c in main['checks'] if c['passed']]+supp['checks']+[{'label':'Fresh natural entry: title/logo visible below sticky bar with no screenshot scroll','passed':natural['passed'],'detail':natural},{'label':'True frozen before and current Workshop matched viewport screenshots','passed':comp['passed'],'detail':comp}]
result={'passed':all(c['passed'] for c in checks),'checkCount':len(checks),'checks':checks,'solved':main['solved'],'layouts':main['layouts']+supp['layouts'],'heightSamples':main['heightSamples'],'sourceSHA256':main['sourceSHA256'],'provenance':{'main55':'diagnostic-main54-assumption-results.json (142 successful assertions before unsupported cross-version assertion)','supplement':'supplement-results.json (completed Main54 gate4 and unaffected mode checks)','naturalEntry':'natural-entry-results.json','visualComparison':'comparison-captures.json','composedGroups':True},'excludedHarnessAssertion':{'original':failed[0],'reason':'Test assumed Main55 earned progress shared into Main54; actual Main54 redirected to its required gate4. This same pre-existing test assumption is documented by the earlier 20261111 game-choice diagnostic; no cross-version progress contract is part of this header change. Corrected focused Main54 gate4 header test passes in supplement.'},'diagnostics':[{'file':'diagnostic-cached-main-results.json','description':'First attempt waited for new logo while before/after used the same top-level URL except fragment. Fresh explicit main query resolved it; exact cached response cause was not independently proved.'},{'file':'diagnostic-main54-assumption-results.json','description':'Main55 checks passed before an unsupported cross-version test assumption; preserved without altering the failed record.'}],'jsExceptions':main['jsExceptions']+supp['jsExceptions']+natural['jsExceptions']+comp['jsExceptions'],'consoleLimits':['Zero JavaScript exceptions captured by the BiDi log subscription in these bounded evidence groups; this is not a clean-console or unrestricted reliability guarantee.','Owned Firefox stderr also contains internal BiDi WeakMap warnings and a molview font-refresh timeout warning on baseline tab shutdown; retained in firefox.log.','The original before-step4-desktop.png was scrolled below the heading by screenshot preparation; use before-top-desktop.png for the visible before header. The original computed before 24px/start/no-logo measurements remain valid.'],'limits':main['limits'],'process':'process.json; owned headless Firefox/server intentionally retained for parent preview; no personal/user GUI browser was controlled.'}
assert result['passed']
(H/'after-results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'passed':result['passed'],'checks':len(checks),'solved':[r['moleculeId'] for r in result['solved']],'jsExceptions':len(result['jsExceptions']),'layouts':len(result['layouts'])},ensure_ascii=False))
